    @if($editable)<script>
    (()=>{const products=@json($catalog);let next={{ $order->items->count() }};const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);const renderOptions=line=>{const product=products.find(p=>p.id==line.querySelector('.product-select').value),area=line.querySelector('.option-area');let old=[...area.querySelectorAll('input:checked')].map(i=>i.value);if(!old.length&&area.dataset.selected)old=JSON.parse(area.dataset.selected).map(String);area.dataset.selected='';area.innerHTML=(product?.groups||[]).map(g=>`<fieldset class="mt-3 border-t pt-3"><legend class="font-bold text-sm">${g.name} <span class="font-normal text-slate-500">(mín. ${g.minimum} · máx. ${g.maximum})</span></legend>${g.options.map(o=>`<label class="mt-2 flex justify-between gap-3 text-sm"><span><input type="checkbox" name="items[${line.dataset.index}][option_ids][]" value="${o.id}" ${old.includes(String(o.id))?'checked':''}> ${o.name}</span><strong>${o.price?'+ '+money(o.price):'Grátis'}</strong></label>`).join('')}</fieldset>`).join('');};const bind=line=>{renderOptions(line);line.querySelector('.product-select').addEventListener('change',()=>renderOptions(line));line.querySelector('.remove-item')?.addEventListener('click',()=>line.remove());};document.querySelectorAll('.item-line').forEach(bind);document.getElementById('addItem').addEventListener('click',()=>{const id=next++,options=products.map(p=>`<option value="${p.id}">${p.name}</option>`).join('');const holder=document.createElement('div');holder.className='item-line rounded-xl border border-slate-200 p-4';holder.dataset.index=id;holder.innerHTML=`<div class="flex flex-wrap items-end gap-3"><div class="min-w-52 flex-1"><label class="text-sm font-bold">Produto</label><select name="items[${id}][product_id]" class="product-select mt-1 w-full rounded-lg border-slate-300">${options}</select></div><label class="w-28 text-sm font-bold">Quantidade<input name="items[${id}][quantity]" value="1" type="number" min="1" max="50" class="mt-1 w-full rounded-lg border-slate-300"></label><button type="button" class="remove-item rounded-lg px-3 py-2 font-bold text-red-700">Remover</button></div><div class="option-area mt-3"></div>`;document.getElementById('orderItems').append(holder);bind(holder);});})();
